@media (min-width: 74rem) {
  .manuscript-scroller[data-living-desk-open] {
    padding-inline-start: 22rem;
  }
  html[data-flow] .manuscript-scroller[data-living-desk-open] {
    padding-inline-start: 0;
  }
}
@media (max-width: 73.99rem) {
  .ld-panel {
.ld-spine__tick--presence {
  background: var(--color-cobalt);
}
.ld-spine__tick.is-faint {
  opacity: 0.35;
}
.ld-spine__tick.is-context {
  opacity: 0.45;
}
.ld-spine__cap {
  position: absolute;
  z-index: 1;
  top: 0;
  left: 0;
  padding: 0 0.25rem;
  transform: translateX(-100%);
  border: 1px solid var(--color-paper-3);
  border-radius: 2px;
  background: var(--color-paper);
  color: var(--color-ink);
  font: 0.6875rem/1.5 var(--font-sans);
  font-variant-numeric: tabular-nums;
  cursor: pointer;
}
.ld-spine__cap[aria-pressed="true"] {
  border-color: var(--color-ink);
}

html[data-flow] .ld-spine,
html[data-flow] .ld-panel {
  display: none;
}

/* ── Themes ─────────────────────────────────────────────── */

[data-theme="nightpress"] .ld-occ[data-ld-lens="stance"].ld-occ--flagged {
  text-decoration-color: var(--color-vermilion);
}
[data-theme="nightpress"] .ld-occrow ins {
  color: var(--color-accent-green);
}

/* ── Reduced motion ─────────────────────────────────────── */

@media (prefers-reduced-motion: reduce) {
  .ld-occ,
  .ld-spine,
  .ld-crit__fill.is-animated {
    transition: none;
  }
  .ld-flash {
    animation: none;
    background: transparent;
  }
  /* The delta pill stays, static, for the same duration. */
  .ld-delta {
    animation: ld-delta-static 2.8s step-end both;
  }
}

.ld-panel .dept-label {
  color: var(--ld-readable-muted);
}
.ld-panel button:focus-visible,
.ld-panel summary:focus-visible,
.ld-spine__cap:focus-visible {
  outline: 2px solid var(--color-cobalt);
  outline-offset: 2px;
}
.ld-panel button:active:not(:disabled) {
  filter: brightness(0.92);
}
.ld-card__head:hover:not(:disabled) .ld-card__title {
  color: var(--color-cobalt);
}
.ld-review-message {
        data-ld-spine
        style={{ height: `${state.height}px` }}
      >
        <button
          type="button"
          class="ld-spine__cap"
          aria-pressed={state.open}
          aria-label="Open the piece"
          title="The piece"
          preventdefault:mousedown
          onClick$={() =>
            window.dispatchEvent(
              new CustomEvent(LIVING_DESK_TOGGLE_EVENT, {
                detail: { open: true },
              }),
            )

